WITH filtered_shipments AS (SELECT * FROM shipments WHERE order_id IS NULL), carrier_summary AS (SELECT carrier, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) AS delivered_count, MIN(delivered_date) AS min_delivered_date FROM filtered_shipments GROUP BY carrier) SELECT carrier, delivered_count, min_delivered_date FROM carrier_summary WHERE delivered_count < 9 ORDER BY delivered_count DESC, carrier LIMIT 10
